package main

import (
	"context"
	"fmt"
	"log"
	"math/big"
	"strings"
	"time"

	"github.com/ethereum/go-ethereum"
	"github.com/ethereum/go-ethereum/accounts/abi"
	"github.com/ethereum/go-ethereum/common"
	"github.com/ethereum/go-ethereum/core/types"
	"github.com/ethereum/go-ethereum/crypto"
	"github.com/ethereum/go-ethereum/ethclient"
)

// --------------------------------------------------------------------------------------------
// 1. 数据来源：直接取自 contracts/Puzzle.go
// --------------------------------------------------------------------------------------------

const puzzleBin = ``

const puzzleABI = `[{"constant":false,"inputs":[{"name":"player","type":"address"}],"name":"endGame","outputs":[],"payable":false,"stateMutability":"nonpayable","type":"function"},{"constant":true,"inputs":[],"name":"manager","outputs":[{"name":"","type":"address"}],"payable":false,"stateMutability":"view","type":"function"},{"constant":false,"inputs":[{"name":"player","type":"address"},{"name":"level","type":"uint256"},{"name":"","type":"string"}],"name":"payout","outputs":[],"payable":false,"stateMutability":"nonpayable","type":"function"},{"constant":false,"inputs":[{"name":"player","type":"address"},{"name":"level","type":"uint256"}],"name":"setLevel","outputs":[],"payable":false,"stateMutability":"nonpayable","type":"function"},{"constant":true,"inputs":[],"name":"getPlayers","outputs":[{"name":"","type":"address[]"}],"payable":false,"stateMutability":"view","type":"function"},{"constant":false,"inputs":[],"name":"play","outputs":[],"payable":true,"stateMutability":"payable","type":"function"},{"constant":false,"inputs":[{"name":"player","type":"address"}],"name":"resetPlayer","outputs":[],"payable":false,"stateMutability":"nonpayable","type":"function"},{"constant":false,"inputs":[],"name":"reset","outputs":[],"payable":false,"stateMutability":"nonpayable","type":"function"},{"constant":true,"inputs":[{"name":"","type":"uint256"}],"name":"players","outputs":[{"name":"","type":"address"}],"payable":false,"stateMutability":"view","type":"function"},{"inputs":[],"payable":true,"stateMutability":"payable","type":"constructor"}]`

func main() {
	client, err := ethclient.Dial("http://127.0.0.1:9500")
	if err != nil {
		log.Fatal(err)
	}

	// 私钥
	privateKey, _ := crypto.HexToECDSA("3836e3675817a46abfadd55b5caec4682a06a919377df79924e75cedbd6eedb6")
	authAddress := crypto.PubkeyToAddress(privateKey.PublicKey)

	nonce, _ := client.PendingNonceAt(context.Background(), authAddress)
	gasPrice, _ := client.SuggestGasPrice(context.Background())
	if gasPrice.Cmp(big.NewInt(0)) == 0 {
		gasPrice = big.NewInt(1000000000)
	}

	// ==========================================
	// 1. 部署官方 Puzzle 合约
	// ==========================================
	fmt.Println("🚀 正在部署官方 Puzzle 合约...")

	bytecode := common.FromHex(puzzleBin)

	deployTx := types.NewContractCreation(nonce, big.NewInt(0), 8000000, gasPrice, bytecode)
	signer := types.NewEIP155Signer(big.NewInt(1666700000))
	signedDeployTx, _ := types.SignTx(deployTx, signer, privateKey)

	client.SendTransaction(context.Background(), signedDeployTx)
	fmt.Printf("⏳ 部署 Hash: %s\n", signedDeployTx.Hash().Hex())

	// 🔥🔥 修复：轮询等待，防止未出块就崩溃 🔥🔥
	var receipt *types.Receipt
	fmt.Printf("⏳ 等待出块中...")
	for i := 0; i < 15; i++ {
		time.Sleep(1 * time.Second)
		receipt, err = client.TransactionReceipt(context.Background(), signedDeployTx.Hash())
		if err == nil && receipt != nil {
			break // 找到了！
		}
		fmt.Printf(".")
	}
	fmt.Println() // 换行

	// 检查是否还没拿到
	if receipt == nil {
		log.Fatal("❌ 等了 15 秒还是没查到交易，可能节点卡住了。")
	}

	if receipt.Status == 0 {
		fmt.Printf("❌ 部署失败 (Status: 0). GasUsed: %d\n", receipt.GasUsed)
		return
	}

	contractAddr := receipt.ContractAddress
	fmt.Printf("✅ 部署成功! 地址: %s\n", contractAddr.Hex())

	// ==========================================
	// 2. 验证：读取管理员地址 (manager)
	// ==========================================
	fmt.Println("👀 正在验证合约读取: 调用 manager()...")

	parsedABI, _ := abi.JSON(strings.NewReader(puzzleABI))
	inputData, _ := parsedABI.Pack("manager")

	msg := ethereum.CallMsg{To: &contractAddr, Data: inputData}
	output, _ := client.CallContract(context.Background(), msg, nil)

	if len(output) == 0 {
		fmt.Println("❌ 读取结果为空")
	} else {
		var managerAddress common.Address
		err = parsedABI.UnpackIntoInterface(&managerAddress, "manager", output)
		if err != nil {
			fmt.Printf("❌ 解析失败: %v\n", err)
		} else {
			fmt.Printf("🎉 成功读取 Manager 地址: %s\n", managerAddress.Hex())
			if managerAddress == authAddress {
				fmt.Println("🏆 Manager 就是您自己！合约逻辑完全正常！")
			}
		}
	}
}
